//! Numerical parity for one native Irodori text-encoder block.
//!
//! The committed fixture is generated by
//! `tools/parity/irodori_text_block_dump_reference.py`, which imports the
//! official `irodori_tts.model.TextBlock` at a pinned upstream revision.

use vokra_core::json::{self, JsonValue};
use vokra_models::irodori::{
    IrodoriTextBlockWeights, IrodoriTextEncoderConfig, irodori_text_block_forward,
};

const FIXTURE: &[u8] = include_bytes!("fixtures/irodori/text_block.json");
const UPSTREAM_REVISION: &str = "8224dafb46d0aba89209a8f905f1cb7e3299d9c1";

fn required<'a>(value: &'a JsonValue, key: &str) -> &'a JsonValue {
    value
        .get(key)
        .unwrap_or_else(|| panic!("Irodori text-block fixture missing `{key}`"))
}

fn usize_field(value: &JsonValue, key: &str) -> usize {
    required(value, key)
        .as_u64()
        .and_then(|value| usize::try_from(value).ok())
        .unwrap_or_else(|| panic!("Irodori fixture `{key}` is not a usize"))
}

fn f32_field(value: &JsonValue, key: &str) -> f32 {
    match required(value, key) {
        JsonValue::Int(value) => *value as f32,
        JsonValue::Float(value) => *value as f32,
        other => panic!("Irodori fixture `{key}` is not numeric: {other:?}"),
    }
}

fn f32_array(value: &JsonValue, key: &str) -> Vec<f32> {
    required(value, key)
        .as_array()
        .unwrap_or_else(|| panic!("Irodori fixture `{key}` is not an array"))
        .iter()
        .enumerate()
        .map(|(index, value)| match value {
            JsonValue::Int(value) => *value as f32,
            JsonValue::Float(value) => *value as f32,
            other => panic!("Irodori fixture `{key}` element {index} is not numeric: {other:?}"),
        })
        .collect()
}

#[test]
fn native_text_block_matches_official_pytorch_layer() {
    let root = json::parse(FIXTURE).expect("parse committed Irodori block fixture");
    assert_eq!(
        required(&root, "upstream_revision").as_str(),
        Some(UPSTREAM_REVISION)
    );
    assert_eq!(
        required(&root, "oracle").as_str(),
        Some("irodori_tts.model.TextBlock.forward")
    );

    let fixture_config = required(&root, "config");
    let config = IrodoriTextEncoderConfig {
        vocab_size: 32,
        dim: usize_field(fixture_config, "dim") as u32,
        n_layer: 1,
        n_head: usize_field(fixture_config, "n_head") as u32,
        mlp_ratio: f32_field(fixture_config, "mlp_ratio"),
        add_bos: true,
    };
    let fixture_weights = required(&root, "weights");
    let weights = IrodoriTextBlockWeights {
        attention_norm: f32_array(fixture_weights, "attention_norm"),
        wq: f32_array(fixture_weights, "wq"),
        wk: f32_array(fixture_weights, "wk"),
        wv: f32_array(fixture_weights, "wv"),
        q_norm: f32_array(fixture_weights, "q_norm"),
        k_norm: f32_array(fixture_weights, "k_norm"),
        gate: f32_array(fixture_weights, "gate"),
        wo: f32_array(fixture_weights, "wo"),
        mlp_norm: f32_array(fixture_weights, "mlp_norm"),
        w1: f32_array(fixture_weights, "w1"),
        w2: f32_array(fixture_weights, "w2"),
        w3: f32_array(fixture_weights, "w3"),
    };
    let key_mask: Vec<bool> = required(&root, "key_mask")
        .as_array()
        .expect("key_mask array")
        .iter()
        .map(|value| match value {
            JsonValue::Bool(value) => *value,
            other => panic!("key_mask element is not boolean: {other:?}"),
        })
        .collect();
    let hidden = f32_array(&root, "hidden");
    let expected = f32_array(&root, "output");
    let actual = irodori_text_block_forward(&config, &weights, &hidden, &key_mask)
        .expect("native Irodori text-block forward");
    assert_eq!(actual.len(), expected.len());

    let mut max_abs = 0.0f32;
    let mut sum_abs = 0.0f64;
    for (&actual, &expected) in actual.iter().zip(&expected) {
        let error = (actual - expected).abs();
        max_abs = max_abs.max(error);
        sum_abs += f64::from(error);
    }
    let mean_abs = sum_abs / actual.len() as f64;
    eprintln!("Irodori official text-block parity: max_abs={max_abs:.9e}, mean_abs={mean_abs:.9e}");

    // Calibrated on the independent official fixture on x86_64 VAST:
    // max_abs=1.192092896e-7, mean_abs=2.312784394e-8. These fixed bounds
    // retain narrow libm/operation-order headroom without masking a changed
    // RoPE layout, mask convention, gate, or residual formula.
    assert!(max_abs < 5.0e-7, "max_abs={max_abs:.9e}");
    assert!(mean_abs < 1.0e-7, "mean_abs={mean_abs:.9e}");
}
